function toggleLanguage(){const e=localStorage.getItem("sjmaths_preferred_language")==="hi"?"en":"hi";localStorage.setItem("sjmaths_preferred_language",e),document.documentElement.lang=e,e==="hi"?(document.body.classList.add("lang-mode-hi"),document.body.classList.remove("lang-mode-en")):(document.body.classList.add("lang-mode-en"),document.body.classList.remove("lang-mode-hi")),document.querySelectorAll("#langBtnText, #mobileLangBtnText, #navLangText").forEach(t=>t.textContent=e==="hi"?"English":"\u0939\u093F\u0928\u094D\u0926\u0940"),window.location.reload&&window.location.reload()}document.addEventListener("DOMContentLoaded",()=>{const e=localStorage.getItem("sjmaths_preferred_language")||"en";document.documentElement.lang=e,e==="hi"&&document.body.classList.add("lang-mode-hi"),document.querySelectorAll("#langBtnText, #mobileLangBtnText, #navLangText").forEach(t=>t.textContent=e==="hi"?"English":"\u0939\u093F\u0928\u094D\u0926\u0940")});
